const defaultNonTTYSummaryDeadline = 5 * time.Minute

// resolveSummaryDeadlineInputs is a small struct so unit tests can inject
// the inputs without touching settings or stderr globals.
type resolveSummaryDeadlineInputs struct {
    settings    time.Duration // explicit override (0 means unset)
    interactive bool          // stderr is a TTY
}

// resolve returns the effective deadline and whether one applies.
// Precedence: explicit settings override > non-interactive default > none.
func (r resolveSummaryDeadlineInputs) resolve() (time.Duration, bool) {
    if r.settings > 0 {
        return r.settings, true
    }
    if !r.interactive {
        return defaultNonTTYSummaryDeadline, true
    }
    return 0, false
}
