Add to `explain.go`:

```go
// startIdleWatchdog cancels the returned context if more than `idle` elapses
// between successive calls to bump(). It is a no-op when idle is zero. Use
// stop() in a defer to release the goroutine; stop() also returns whether
// the watchdog fired (true means the context was canceled by the watchdog).
func startIdleWatchdog(parent context.Context, idle time.Duration, lastIdle *time.Time) (ctx context.Context, fired *atomic.Bool, stop func()) {
    fired = &atomic.Bool{}
    if idle <= 0 {
        return parent, fired, func() {}
    }
    ctx, cancel := context.WithCancel(parent)
    done := make(chan struct{})
    go func() {
        ticker := time.NewTicker(idle / 4) // poll at 1/4 the idle window
        defer ticker.Stop()
        for {
            select {
            case <-ticker.C:
                if time.Since(*lastIdle) >= idle {
                    fired.Store(true)
                    cancel()
                    return
                }
            case <-done:
                return
            case <-parent.Done():
                return
            }
        }
    }()
    return ctx, fired, func() { close(done); cancel() }
}
