```go
// summaryProgressWriter renders agent.GenerationProgress events to the
// configured writer using the existing statusStyles helper. On a TTY (and
// outside ACCESSIBLE mode) it rewrites the current line for the running
// token count; otherwise it appends one line per non-deduplicated event.
type summaryProgressWriter struct {
    w        io.Writer
    styles   statusStyles
    inplace  bool
    lastIdle time.Time
    lastLine string
}

func newSummaryProgressWriter(w io.Writer) *summaryProgressWriter {
    return &summaryProgressWriter{
        w:       w,
        styles:  newStatusStyles(w),
        inplace: isTerminalWriter(w) && !IsAccessibleMode(),
    }
}

func (s *summaryProgressWriter) handle(p agent.GenerationProgress) {
    s.lastIdle = time.Now()
    arrow := s.styles.render(s.styles.cyan, "→")
    check := s.styles.render(s.styles.green, "✓")
    switch p.Phase {
    case agent.PhaseConnecting:
        s.printLine(fmt.Sprintf("%s Sending request to Anthropic…", arrow))
    case agent.PhaseFirstToken:
        s.printLine(fmt.Sprintf(
            "%s Anthropic responded (TTFT %s, %s cached input tokens) — generating…",
            arrow, formatMs(p.TTFTms), formatTokenCount(p.CachedInputTokens)))
    case agent.PhaseGenerating:
        s.updateLine(fmt.Sprintf(
            "%s Writing summary… (~%s tokens)",
            arrow, formatTokenCount(p.OutputTokens)))
    case agent.PhaseDone:
        s.printLine(fmt.Sprintf(
            "%s Summary generated (%s, %s output tokens)",
            check, formatMs(p.DurationMs), formatTokenCount(p.OutputTokens)))
    }
}

func (s *summaryProgressWriter) printLine(line string) {
    if s.inplace && s.lastLine != "" {
        // Clear the in-place line before appending a final one.
        fmt.Fprint(s.w, "\r\033[2K")
    }
    fmt.Fprintln(s.w, line)
    s.lastLine = ""
}

func (s *summaryProgressWriter) updateLine(line string) {
    if s.lastLine == line {
        return // dedup identical consecutive updates
    }
    if s.inplace {
        fmt.Fprintf(s.w, "\r\033[2K%s", line)
    } else {
        fmt.Fprintln(s.w, line)
    }
    s.lastLine = line
}

// formatMs formats a millisecond count as "1.5s" / "120ms".
func formatMs(ms int) string {
    if ms < 1000 {
        return fmt.Sprintf("%dms", ms)
    }
    return fmt.Sprintf("%.1fs", float64(ms)/1000.0)
}
```

**Key design:**
- `newSummaryProgressWriter` constructs using `newStatusStyles(w)` and `isTerminalWriter(w)` from `status_style.go`, plus `IsAccessibleMode()` from `utils.go`.
- `formatTokenCount` is already in `status_style.go` — reuse directly, don't redefine.
- `arrow` and `check` get styled (colored) via `s.styles.render(style, text)` which no-ops when color is disabled.
- `inplace` mode uses `\r\033[2K` (carriage return + clear line) for the Generating phase. Non-TTY or accessible mode falls back to one line per event.
- Dedup on `lastLine` prevents identical consecutive Generating updates (same token count) from producing duplicate lines.
- `lastIdle` is updated on every event — the idle watchdog (Task 10) reads this.

