// startIdleWatchdog cancels the returned context if more than idle elapses
// between successive updates to *lastIdle. It is a no-op when idle <= 0.
// stop() must be called in a defer to release the goroutine; fired reports
// whether the watchdog was the reason for cancellation.
func startIdleWatchdog(parent context.Context, idle time.Duration, lastIdle *time.Time) (ctx context.Context, fired *atomic.Bool, stop func()) {
    fired = &atomic.Bool{}
    if idle <= 0 {
        return parent, fired, func() {}
    }
    ctx, cancel := context.WithCancel(parent)
    done := make(chan struct{})
    go func() {
        poll := idle / 4
        if poll < time.Millisecond {
            poll = time.Millisecond
        }
        ticker := time.NewTicker(poll)
        defer ticker.Stop()
        for {
            select {
            case <-ticker.C:
                if time.Since(*lastIdle) >= idle {
                    fired.Store(true)
                    cancel()
                    return
                }
            case <-done:
                return
            case <-parent.Done():
                return
            }
        }
    }()
    return ctx, fired, func() { close(done); cancel() }
}
