81	// streamClaudeResponse reads NDJSON-encoded events from r, invokes onEvent
82	// for every successfully decoded event, and returns the final result event
83	// once the stream ends. Malformed lines are skipped silently to keep the
84	// stream resilient against single-line corruption. If the stream ends
85	// without ever producing a result event, returns (nil, error).
86	func streamClaudeResponse(r io.Reader, onEvent func(StreamEvent)) (*StreamEvent, error) {
