Add a test that exercises the idle-watchdog path through `generateCheckpointAISummary`. This is the path where `summaryDeadlineResolver` returns `(duration, true)` AND `isTerminalWriter` returns false AND `settingsTimeoutUnset` returns true — causing the idle watchdog to be used instead of `context.WithTimeout`.

```go
func TestGenerateCheckpointAISummary_IdleWatchdogPath(t *testing.T) {
    // This test exercises the non-interactive idle-watchdog code path.
    // It sets: resolver returns (short deadline, true), settingsTimeoutUnset returns true,
    // errW is not a terminal. The mock generator never bumps lastActivity, so the
    // idle watchdog should fire and cancel the context.
    prevResolver := summaryDeadlineResolver
    summaryDeadlineResolver = func(io.Writer) (time.Duration, bool) {
        return 50 * time.Millisecond, true
    }
    t.Cleanup(func() { summaryDeadlineResolver = prevResolver })

    prevSettings := settingsTimeoutUnset
    settingsTimeoutUnset = func() bool { return true }
    t.Cleanup(func() { settingsTimeoutUnset = prevSettings })

    tmpGenerator := generateTranscriptSummary
    generateTranscriptSummary = func(
        ctx context.Context,
        _ redact.RedactedBytes,
        _ []string,
        _ types.AgentType,
        _ summarize.Generator,
        _ agent.ProgressFn,
    ) (*checkpoint.Summary, error) {
        // Don't call the progress callback — idle watchdog should fire
        <-ctx.Done()
        return nil, ctx.Err()
    }
    t.Cleanup(func() { generateTranscriptSummary = tmpGenerator })

    _, err := generateCheckpointAISummary(context.Background(), io.Discard, []byte("transcript"), nil, "Claude Code")
    if err == nil {
        t.Fatal("expected error from idle watchdog")
    }
    if !errors.Is(err, context.Canceled) && !errors.Is(err, context.DeadlineExceeded) {
        t.Fatalf("expected context error, got: %v", err)
    }
}
```

IMPORTANT: This test mutates package-level vars (`summaryDeadlineResolver`, `settingsTimeoutUnset`, `generateTranscriptSummary`), so do NOT add `t.Parallel()`.

