// settingsTimeoutUnset reports whether the user has NOT configured an explicit
// summary timeout in settings.json. Package-level var so tests can substitute.
var settingsTimeoutUnset = func() bool {
	s, _ := settings.Load(context.Background()) //nolint:errcheck // empty settings on error is acceptable
	return s.SummaryTimeoutValue() == 0
}

func formatSummaryTimeout(d time.Duration) string {
	if d < 0 {
		d = 0
	}
	if d < time.Second {
		return d.Round(10 * time.Millisecond).String()
	}
	return d.Round(time.Second).String()

