// deadlineMode describes how the summary deadline should be applied.
type deadlineMode int

const (
	deadlineModeNone      deadlineMode = iota // interactive TTY: no deadline, user Ctrl+C
	deadlineModeIdle                          // non-interactive default: idle-based watchdog
	deadlineModeHardClock                     // explicit settings override: wall-clock timeout
)

// summaryDeadlineResult is the resolved deadline policy for a single
// summary generation, computed once from settings + TTY state.
type summaryDeadlineResult struct {
	mode     deadlineMode
	duration time.Duration // zero when mode == deadlineModeNone
}

// summaryDeadlineResolver is package-level so tests can substitute the
// resolution policy without touching settings or stderr.
var summaryDeadlineResolver = func(errW io.Writer) summaryDeadlineResult {
	s, _ := settings.Load(context.Background()) //nolint:errcheck // empty settings on error is acceptable
	settingsTimeout := s.SummaryTimeoutValue()
	interactive := isTerminalWriter(errW)

	d, hasDeadline := resolveSummaryDeadlineInputs{
		settings:    settingsTimeout,
		interactive: interactive,
	}.resolve()

	if !hasDeadline {
		return summaryDeadlineResult{mode: deadlineModeNone}
	}
	if settingsTimeout > 0 {
		return summaryDeadlineResult{mode: deadlineModeHardClock, duration: d}
	}
	return summaryDeadlineResult{mode: deadlineModeIdle, duration: d}
}

