// looksLikeUnrecognizedFlag returns true if stderr indicates the CLI
// rejected a flag (e.g., older Claude CLI that doesn't support stream-json).
func looksLikeUnrecognizedFlag(stderr string) bool {
	lower := strings.ToLower(stderr)
	return strings.Contains(lower, "unrecognized option") ||
		strings.Contains(lower, "unknown flag") ||
		strings.Contains(lower, "unknown option") ||
		strings.Contains(lower, "invalid option")
}

// generateTextLegacy is the fallback path for Claude CLIs that don't support
// --output-format stream-json. Uses the original --output-format json mode
// with no progress reporting.
func (c *ClaudeCodeAgent) generateTextLegacy(ctx context.Context, prompt, model string) (string, error) {
	commandRunner := c.CommandRunner
	if commandRunner == nil {
		commandRunner = exec.CommandContext
	}

	cmd := commandRunner(ctx, "claude",
		"--print", "--output-format", "json",
		"--model", model, "--setting-sources", "")

	cmd.Dir = os.TempDir()
	cmd.Env = stripGitEnv(os.Environ())
	cmd.Stdin = strings.NewReader(prompt)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded //nolint:wrapcheck // sentinel passthrough
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return "", context.Canceled //nolint:wrapcheck // sentinel passthrough
		}
		if isExecError(err) {
			return "", &ClaudeError{Kind: ClaudeErrorCLIMissing, Cause: err}
		}
		// Try structured envelope on exit 0 with error or non-zero exit.
		if _, env, parseErr := parseGenerateTextResponse(stdout.Bytes()); parseErr == nil && env != nil && env.IsError {
