9	type responseEnvelope struct {
10		Type   string  `json:"type"`
11		Result *string `json:"result"`
12	}
13	
14	// parseGenerateTextResponse extracts the raw text payload from Claude CLI JSON output.
15	// Claude may return either a legacy single object or a newer array of events.
16	func parseGenerateTextResponse(stdout []byte) (string, error) {
17		var response responseEnvelope
18		if err := json.Unmarshal(stdout, &response); err == nil && response.Result != nil {
19			return *response.Result, nil
20		}
21	
22		var responses []responseEnvelope
23		if err := json.Unmarshal(stdout, &responses); err != nil {
24			return "", fmt.Errorf("unsupported Claude CLI JSON response: %w", err)
25		}
26	
27		for i := len(responses) - 1; i >= 0; i-- {
28			if responses[i].Type == "result" && responses[i].Result != nil {
29				return *responses[i].Result, nil
30			}
31		}
32	
33		return "", errors.New("unsupported Claude CLI JSON response: missing result item")
34	}

